  "decisions": [
    {
      "id": "D1",
      "title": "Pre-aggregated Daily Counters vs Individual Event Log Rows",
      "choice": "Store daily clicks in a pre-aggregated ShortLinkDailyClick table keyed uniquely on (ShortLinkId, Date).",
      "rationale": "High-traffic redirect endpoints would suffer unbounded storage growth and costly run-time GROUP BY aggregations if every click were stored as an individual row. A pre-aggregated daily counter provides O(1) upsert during redirection and O(N) bounded retrieval for up to 90 days.",
      "alternatives": [
        "Individual ClickEvents table recording timestamp, IP, and ShortLinkId",
        "JSON column on ShortLink containing serialized daily counts"
      ]
    },
    {
      "id": "D2",
      "title": "In-Memory Date Range Zero-Filling",
      "choice": "Query existing records for the link between (TodayUtc - days + 1) and TodayUtc, projecting into a dictionary, then generate all N consecutive dates in C# memory zero-filling dates with no clicks.",
      "rationale": "SQLite lacks built-in calendar tables or recursive CTE convenience across all configurations. Since N is capped at 90, in-memory zero-filling is negligible in CPU and memory overhead while ensuring deterministic chronological ascending order.",
      "alternatives": [
        "Recursive common table expression (CTE) in SQL generating calendar dates",
        "Pre-populating 90 days of zero rows at link creation time"
      ]
    },
    {
      "id": "D3",
      "title": "Strict Query Parameter Parsing and Validation",
      "choice": "Explicitly parse the 'days' query string parameter using int.TryParse and validate (1 <= days <= 90), returning HTTP 400 Bad Request with ErrorResponse if invalid or missing format.",
      "rationale": "Protects against unexpected inputs, injection attempts, and invalid boundary queries without bubbling unhandled exceptions.",
      "alternatives": [
